        public WadFile(string path){PathName=Path.GetFullPath(path);byte[] b=File.ReadAllBytes(path);Bin.Require(b.Length>=12,"WAD header is truncated.");string magic=Encoding.ASCII.GetString(b,0,4);Bin.Require(magic=="IWAD"||magic=="PWAD","Choose a Doom IWAD or PWAD.");int count=BitConverter.ToInt32(b,4),directory=BitConverter.ToInt32(b,8);Bin.Require(count>=0&&count<=100000&&directory>=12&&(long)directory+count*16L<=b.Length,"Invalid WAD directory.");
            for(int i=0;i<count;i++){int p=directory+i*16,offset=BitConverter.ToInt32(b,p),length=BitConverter.ToInt32(b,p+4);Bin.Require(offset>=0&&length>=0&&(long)offset+length<=b.Length,"WAD lump is outside the file.");string name=Name(b,p+8);byte[] data=new byte[length];Buffer.BlockCopy(b,offset,data,0,length);Lumps.Add(new Lump{Name=name,Data=data});if(Regex.IsMatch(name,"^E[1-9]M[1-9]$")){Bin.Require(!Levels.Contains(name),"Duplicate level marker: "+name);Levels.Add(name);}}
            Bin.Require(Levels.Count>0,"No Doom 1 E#M# maps found. Hexen/UDMF and Doom 2 MAP## maps are unsupported.");
        }
        public static string Name(byte[] b,int p){return Encoding.ASCII.GetString(b,p,8).TrimEnd('\0').ToUpperInvariant();}
        public Dictionary<string,byte[]> Map(string level){int start=Lumps.FindIndex(l=>l.Name==level);Bin.Require(start>=0,"Missing map "+level);var result=new Dictionary<string,byte[]>();for(int i=start+1;i<Lumps.Count;i++){string name=Lumps[i].Name;if(Regex.IsMatch(name,"^(E[1-9]M[1-9]|MAP[0-9][0-9])$"))break;Bin.Require(name!="BEHAVIOR"&&name!="TEXTMAP","Only classic Doom binary maps are supported.");if(new[]{"VERTEXES","LINEDEFS","SIDEDEFS","SECTORS","THINGS"}.Contains(name)){Bin.Require(!result.ContainsKey(name),"Duplicate map lump "+name);result[name]=Lumps[i].Data;}}foreach(string key in new[]{"VERTEXES","LINEDEFS","SIDEDEFS","SECTORS","THINGS"})Bin.Require(result.ContainsKey(key),level+" is missing "+key);return result;}
    }
    public sealed class WadConverter {
        readonly Rom rom;readonly CompatibilityActions compatibility;readonly Dictionary<string,int> walls=new Dictionary<string,int>(),flats=new Dictionary<string,int>();readonly Dictionary<string,string> aliases=new Dictionary<string,string>();
        public readonly List<string> Report=new List<string>();readonly HashSet<string> warnings=new HashSet<string>();public bool AllowLossy;public ConversionOptions Options=new ConversionOptions();
        static readonly int[] PcThings={1,2,3,4,11,14,3004,9,3001,3002,3005,3006,3003,16,7,2001,2005,2002,2003,2004,2006,13,5,6,38,40,39,8,2007,2048,2008,2049,2010,2046,2047,17,2011,2012,2014,2015,2018,2019,2013,2022,2023,2024,2025,2026,2045,2035,2028,10,18,21,27,31,34,35,28,43,44,47,48,55};
        public WadConverter(Rom source,string resources){rom=source;compatibility=new CompatibilityActions(resources);
            string[] lines=File.ReadAllLines(Path.Combine(resources,"TextureList.txt"));for(int i=0;i<lines.Length;i++){string line=lines[i];if(line.Length==0||char.IsWhiteSpace(line[0])||!line.Contains(","))continue;string name=line.Split(',')[0];if(i+1>=lines.Length)break;string next=lines[++i];if(next.StartsWith(" ")){while(i<lines.Length&&lines[i].StartsWith(" "))i++;int number;Bin.Require(i<lines.Length&&int.TryParse(lines[i],out number),"Invalid DoomFX texture mapping.");walls[name]=int.Parse(lines[i])*2;}else aliases[name]=next.Split(',')[0];}
            lines=File.ReadAllLines(Path.Combine(resources,"FloorList.txt"));for(int i=0;i+2<lines.Length;i+=4){int colour;Bin.Require(int.TryParse(lines[i+2],out colour),"Invalid DoomFX floor mapping.");flats[lines[i]]=colour;}
        }
        void Warn(string text){if(warnings.Add(text))Report.Add("SUBSTITUTION: "+text);}
        int Wall(string name){string original=name;var visited=new HashSet<string>();while(aliases.ContainsKey(name)&&visited.Add(name))name=aliases[name];int id;if(walls.TryGetValue(name,out id)&&rom.WallTextures.Contains(id)){if(name!=original)Warn(original+" -> "+name+" (ROM wall "+id+")");return id;}if(original!="-") {Bin.Require(AllowLossy,"Unmapped wall texture "+original+". Enable substitutions or use a supported Doom texture.");Warn(original+" -> default ROM wall 2");}return rom.WallTextures.Contains(2)?2:rom.WallTextures[0];}
        int Flat(string name,bool ceiling){if(name.StartsWith("F_SKY")){Bin.Require(ceiling,"Sky is only valid on a ceiling.");return 255;}int colour;if(flats.TryGetValue(name,out colour))return Math.Max(1,Math.Min(254,colour));Bin.Require(AllowLossy,"Unmapped flat "+name+". Enable substitutions to use colour 6.");Warn(name+" -> solid colour 6");return 6;}
        static byte[] Records(Dictionary<string,byte[]> lumps,string name,int size){byte[] b=lumps[name];Bin.Require(b.Length%size==0,"Invalid "+name+" record size.");return b;}
        public Map Import(WadFile wad,string level,int slot,bool merge){var lumps=wad.Map(level);var timedDoors=new List<int>();var m=new Map{Slot=slot,Name=level+" (SNES)",SourceMarker=level,EditGeometry=true,RoomTexture=2};
            var tags=ConversionOptimizer.Tags(Records(lumps,"SECTORS",26),Records(lumps,"LINEDEFS",14),Options.CompactTags,Report);byte[] b=Records(lumps,"VERTEXES",4);for(int p=0;p<b.Length;p+=4)m.Vertices.Add(new Point(Bin.S16(b,p),Bin.S16(b,p+2)));
            b=Records(lumps,"SECTORS",26);for(int p=0;p<b.Length;p+=26){int type=Bin.U16(b,p+22),tag=tags[Bin.U16(b,p+24)];Bin.Require(tag<=255,"Sector tag exceeds 255.");bool manualDoor;type=compatibility.Sector(type,Options.ClosestActions,AllowLossy,out manualDoor,Warn);if(manualDoor)timedDoors.Add(m.Sectors.Count);int dark=Math.Max(0,Math.Min(247,255-Bin.U16(b,p+20)));m.Sectors.Add(new Sector{Floor=Bin.S16(b,p),Ceiling=Bin.S16(b,p+2),FloorTexture=Flat(WadFile.Name(b,p+4),false),CeilingTexture=Flat(WadFile.Name(b,p+12),true),Darkness=dark,NeighborDarkness=dark,Type=type,Tag=tag});}
            byte[] sides=Records(lumps,"SIDEDEFS",30);b=Records(lumps,"LINEDEFS",14);
            for(int p=0;p<b.Length;p+=14){int a=Bin.U16(b,p),z=Bin.U16(b,p+2),flags=Bin.U16(b,p+4),action=Bin.U16(b,p+6),tag=tags[Bin.U16(b,p+8)],right=Bin.U16(b,p+10),left=Bin.U16(b,p+12);Bin.Require(a<m.Vertices.Count&&z<m.Vertices.Count&&a!=z,"Invalid linedef vertices.");Bin.Require(right<sides.Length/30&& (left==65535||left<sides.Length/30),"Invalid sidedef index.");Bin.Require(tag<=255,"Linedef tag exceeds 255.");
                if((flags&2)!=0){Warn("PC monster-only blocking flag dropped; explicit impassable flags are preserved");flags&=~2;}
                action=compatibility.Line(action,Options.ClosestActions,AllowLossy,Warn,left!=65535&&(flags&3)==0);if(action==51){Warn("Secret exits become normal exits in the selected-level campaign");action=11;}
                if((flags&0x18)!=0)Warn("PC texture unpegging flags have no native equivalent and are omitted");
                int near=Bin.U16(sides,right*30+28),far=left==65535?-1:Bin.U16(sides,left*30+28);Bin.Require(near<m.Sectors.Count&&(far<0||far<m.Sectors.Count),"Sidedef references an invalid sector.");
                Face front=GeometryTools.AddFace(m,near,far,Wall(WadFile.Name(sides,right*30+(far<0?20:4))));front.Lower=Wall(WadFile.Name(sides,right*30+12));var w=new Wall{Start=a,End=z,Face=front.Offset,Flags=(far<0?1:0)|((flags&3)!=0?8:0)|((flags&32)!=0?4:0)|((flags&128)!=0?32:0),Type=action,Tag=tag,OffsetX=Bin.S16(sides,right*30)&255,OffsetY=Bin.S16(sides,right*30+2)&255};
                if(far>=0){Face back=GeometryTools.AddFace(m,far,near,Wall(WadFile.Name(sides,left*30+4)));back.Lower=Wall(WadFile.Name(sides,left*30+12));w.BackFace=back.Offset;if(Bin.S16(sides,left*30)!=Bin.S16(sides,right*30)||Bin.S16(sides,left*30+2)!=Bin.S16(sides,right*30+2))Warn("Different front/back offsets use the front offset in the native line format");if(WadFile.Name(sides,right*30+20)!="-"||WadFile.Name(sides,left*30+20)!="-"){Warn("Masked middle portal textures omitted by default; existing portal geometry and explicit blocking are preserved");}}m.Walls.Add(w);
            }
            foreach(int door in timedDoors){var boundaries=GeometryTools.Boundary(m,door).Select(i=>m.Walls[i]).Where(w=>GeometryTools.Far(m,w)>=0).ToArray();Bin.Require(boundaries.Length>0&&boundaries.All(w=>w.Type==0),"Timed sector "+door+" cannot become a manual door without replacing existing boundary actions. Edit it in the source PWAD.");GeometryTools.Preset(m,door,SectorMotion.Door);}
            b=Records(lumps,"THINGS",10);for(int p=0;p<b.Length;p+=10){int pc=Bin.U16(b,p+6),flags=Bin.U16(b,p+8);if((flags&16)!=0)continue;int type=pc==58?9:Array.IndexOf(PcThings,pc);if(type>=1&&type<=4)continue;if(type<0){Bin.Require(AllowLossy,"Unsupported thing "+pc+". Enable substitutions to omit it.");Warn("Thing "+pc+" omitted");continue;}int skills=flags&7;if(type==0)skills=7;if(skills==0)continue;Thing template=rom.Project.Maps.SelectMany(x=>x.Things).FirstOrDefault(t=>t.Type==type);int nativeFlags=template==null?(type<=14?0xe8:type==49?0xa8:0x80):template.Flags&0xe8;m.Things.Add(new Thing{Type=type,X=Bin.S16(b,p),Y=Bin.S16(b,p+2),Angle=(Bin.U16(b,p+4)%360)*65536/360,Flags=nativeFlags|skills});}
            Bin.Require(m.Things.Count(t=>t.Type==0)==1,"Map needs exactly one single-player start.");Options.MergeSectors=merge;ConversionOptimizer.Apply(rom,m,Options,Report,delegate{Merge(m);});Report.Add(level+": "+m.Sectors.Count+" sectors, "+m.Walls.Count+" lines, "+m.Things.Count+" things");return m;
        }
        public void Merge(Map m){int old=m.Sectors.Count;var protectedSectors=new HashSet<int>();foreach(Wall w in m.Walls.Where(w=>w.Type!=0)){protectedSectors.Add(GeometryTools.Near(m,w));protectedSectors.Add(GeometryTools.Far(m,w));foreach(int i in Enumerable.Range(0,m.Sectors.Count).Where(i=>w.Tag!=0&&m.Sectors[i].Tag==w.Tag))protectedSectors.Add(i);}
            var parent=Enumerable.Range(0,m.Sectors.Count).ToArray();Func<int,int> root=null;root=i=>parent[i]==i?i:(parent[i]=root(parent[i]));foreach(Wall w in m.Walls){int a=GeometryTools.Near(m,w),b=GeometryTools.Far(m,w);if(a<0||b<0||w.Type!=0||(w.Flags&12)!=0||protectedSectors.Contains(a)||protectedSectors.Contains(b))continue;Sector x=m.Sectors[a],y=m.Sectors[b];if(x.Floor==y.Floor&&x.Ceiling==y.Ceiling&&x.FloorTexture==y.FloorTexture&&x.CeilingTexture==y.CeilingTexture&&x.Darkness==y.Darkness&&x.NeighborDarkness==y.NeighborDarkness&&x.Type==0&&y.Type==0&&x.Tag==0&&y.Tag==0)parent[root(b)]=root(a);}
            var roots=Enumerable.Range(0,parent.Length).Select(root).Distinct().ToList();foreach(Face f in m.Faces){f.Near=roots.IndexOf(root(f.Near));if(f.Far>=0)f.Far=roots.IndexOf(root(f.Far));}m.Sectors=roots.Select(i=>m.Sectors[i]).ToList();m.Walls.RemoveAll(w=>{Face f=GeometryTools.Front(m,w);return !f.Solid&&f.Near==f.Far&&w.Type==0&&(w.Flags&12)==0;});var usedFaces=new HashSet<int>(m.Walls.SelectMany(w=>new[]{w.Face,w.BackFace}));m.Faces.RemoveAll(f=>!usedFaces.Contains(f.Offset));var used=m.Walls.SelectMany(w=>new[]{w.Start,w.End}).Distinct().OrderBy(i=>i).ToList();foreach(Wall w in m.Walls){w.Start=used.IndexOf(w.Start);w.End=used.IndexOf(w.End);}m.Vertices=used.Select(i=>m.Vertices[i]).ToList();Report.Add("Optimization: "+(old-m.Sectors.Count)+" static sectors merged; action-linked sectors preserved.");}
        public byte[] Convert(WadFile wad,string[] levels,bool merge){Bin.Require(levels.Length>0&&levels.Length<=rom.Project.Maps.Count,"Select between 1 and 22 maps.");var available=rom.Project.Maps.Select(m=>m.Slot).OrderBy(i=>i).ToList();var assigned=new List<int>();for(int i=0;i<levels.Length;i++){Map map=Import(wad,levels[i],available[0],merge);int chosen=-1;string failure="";foreach(int candidate in Options.BestFit?available.OrderBy(c=>i==0&&c==0?-1:i>0&&(c==9||c==18)?int.MaxValue:rom.GetSection(c,"A").Size).ThenBy(c=>rom.GetSection(c,"B").Size):available.AsEnumerable()){if(i>0&&candidate==0)continue;map.Slot=candidate;try{rom.Validate(map);NativeBuildInfo budget=NativeCompiler.Build(rom,(byte[])rom.Bytes.Clone(),map);ConversionOptimizer.Budget(map,budget,Report);chosen=candidate;break;}catch(InvalidDataException ex){failure=ex.Message;if(!failure.Contains("bytes; this slot has"))throw new InvalidDataException(levels[i]+": "+failure,ex);}}Bin.Require(chosen>=0,levels[i]+" does not fit any remaining native slot. "+failure);map.Slot=chosen;assigned.Add(chosen);available.Remove(chosen);rom.Project.Maps[rom.Project.Maps.FindIndex(m=>m.Slot==chosen)]=map;Report.Add(levels[i]+" stored in E"+(chosen/9+1)+"M"+(chosen%9+1)+" (native byte budget verified).");}int[] slots=assigned.ToArray();
            rom.Project.CampaignSlots=slots;byte[] image=rom.Compile();Report.Add(CampaignStorage.Report(rom.Budget).TrimEnd());if(slots[0]!=0)Report.Add("E1M1 start aliases the first converted map; campaign metadata keeps this mapping when editing the project.");return image;}
        public static void ApplyCampaign(byte[] image,int[] slots){if(slots[0]!=0)foreach(int table in Rom.Tables){int size=table==0x32a8||table==0x3566?4:2;Buffer.BlockCopy(image,Rom.TableBank+table+slots[0]*size,image,Rom.TableBank+table,size);}int[] route=(int[])slots.Clone();route[0]=0;PatchCampaign(image,route);Checksum(image);}
        // Verified USA retail NextLevelI byte pattern, from DoomFX rage.a.
        // Route the last selected slot to 27, the native ScoreE3Text/game-over sentinel.
        public static void PatchCampaign(byte[] image,int[] slots){byte[] pattern={1,2,3,4,5,6,7,9,3,10,11,12,13,14,15,16,18,12,19,20,21,22,23,24,25,27,24};int found=-1;for(int i=0;i<=image.Length-pattern.Length;i++){int j=0;while(j<pattern.Length&&image[i+j]==pattern[j])j++;if(j==pattern.Length){Bin.Require(found<0,"Ambiguous next-level table; ROM export stopped.");found=i;}}Bin.Require(found>=0,"USA next-level table was not found; ROM export stopped.");for(int i=0;i<slots.Length;i++)image[found+slots[i]]=(byte)(i+1<slots.Length?slots[i+1]:27);byte[] skillGate={0xc0,0x12,0xf0,0x69,0x3a,0xf0,0x04,0xc0,0x09,0xf0,0x62};Bin.Require(image.Skip(0x1ffb4d).Take(skillGate.Length).SequenceEqual(skillGate),"Unexpected USA episode difficulty gate; ROM export stopped.");image[0x1ffb4e]=255;image[0x1ffb55]=255;}
